-- ============================================================================
-- Verbista 0017: onboarding ("La Biblioteca del Olvido")
-- Paste into the Supabase SQL editor and run. It runs in one transaction,
-- either all of it applies or none of it.
--
-- Same schema as lib/db/migrations/0017_onboarding.sql (generated by
-- drizzle-kit from lib/db/schema), plus:
--   * idempotency: IF NOT EXISTS / constraint guards, safe to run twice;
--   * a backfill so EXISTING users are treated as already onboarded.
-- After running it, `npm run db:push` should report no changes.
-- ============================================================================

BEGIN;

-- ─── languages: placement result and onboarding state ───────────────────────
-- onboarded_at NULL = this language still needs its onboarding flow.
ALTER TABLE public.languages ADD COLUMN IF NOT EXISTS level           text;
ALTER TABLE public.languages ADD COLUMN IF NOT EXISTS onboarding_path text;
ALTER TABLE public.languages ADD COLUMN IF NOT EXISTS onboarded_at    timestamp;

-- ─── words: where the row came from + starter-deck fields ───────────────────
-- A constant DEFAULT is metadata-only in Postgres 11+, so no table rewrite.
ALTER TABLE public.words ADD COLUMN IF NOT EXISTS origin     text DEFAULT 'text' NOT NULL;
ALTER TABLE public.words ADD COLUMN IF NOT EXISTS deck_order integer;
ALTER TABLE public.words ADD COLUMN IF NOT EXISTS glyph      text;

-- ─── series: starter story marker ───────────────────────────────────────────
ALTER TABLE public.series ADD COLUMN IF NOT EXISTS kind text DEFAULT 'user' NOT NULL;

-- ─── Indexes ────────────────────────────────────────────────────────────────
-- SRS starter-deck drip: next UNKNOWN deck cards in deck_order (partial index).
CREATE INDEX IF NOT EXISTS words_starter_deck_idx
  ON public.words USING btree (user_id, language_id, deck_order)
  WHERE origin = 'starter_deck';

-- At most one starter story per user and language (makes seeding idempotent).
CREATE UNIQUE INDEX IF NOT EXISTS series_one_starter_story_idx
  ON public.series USING btree (user_id, language_id)
  WHERE kind = 'starter_story';

-- ─── CHECK constraints (guarded, since ADD CONSTRAINT has no IF NOT EXISTS) ──
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'languages_level_check') THEN
    ALTER TABLE public.languages ADD CONSTRAINT languages_level_check
      CHECK (level IS NULL OR level IN ('A1','A2','B1','B2','C1','C2'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'languages_onboarding_path_check') THEN
    ALTER TABLE public.languages ADD CONSTRAINT languages_onboarding_path_check
      CHECK (onboarding_path IS NULL OR onboarding_path IN ('beginner','placement','self'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'words_origin_check') THEN
    ALTER TABLE public.words ADD CONSTRAINT words_origin_check
      CHECK (origin IN ('text','placement','starter_deck','import'));
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'series_kind_check') THEN
    ALTER TABLE public.series ADD CONSTRAINT series_kind_check
      CHECK (kind IN ('user','starter_story'));
  END IF;
END $$;

-- ─── Backfill: existing users keep their current experience ─────────────────
-- Every language that exists today was set up before this onboarding existed,
-- so mark it onboarded. Otherwise current users would be sent into the wizard.
-- (onboarding_path stays NULL: "pre-onboarding language".)
UPDATE public.languages
   SET onboarded_at = created_at
 WHERE onboarded_at IS NULL;

COMMIT;

-- ─── Verify (optional, run after) ───────────────────────────────────────────
-- SELECT count(*) FILTER (WHERE onboarded_at IS NULL) AS languages_needing_onboarding,
--        count(*)                                     AS languages_total
--   FROM public.languages;
-- Expected right after running: languages_needing_onboarding = 0.
